import asyncio, json
from playwright.async_api import async_playwright
B='http://localhost:4000'; res=[]
def chk(name, ok, detail=''):
    res.append((name, bool(ok), str(detail))); print('PASS' if ok else 'FAIL', name, detail)
async def shot(p,name,full=True): await p.screenshot(path=f'/tmp/shots3/{name}.png',full_page=full)
async def login(p,email,pw):
    await p.goto(B); await p.fill('#email',email); await p.fill('#password',pw); await p.click('button[type=submit]'); await p.wait_for_selector('.topbar')
async def main():
    async with async_playwright() as pw:
        br=await pw.chromium.launch(channel='chrome',args=['--no-sandbox'])
        mk=lambda w=1280,h=900,m=False: br.new_context(viewport={'width':w,'height':h},is_mobile=m,device_scale_factor=2 if m else 1)
        errs=[]
        sc=await mk(); st=await sc.new_page(); st.on('pageerror',lambda e:errs.append(str(e)))
        ec=await mk(); ed=await ec.new_page(); ed.on('pageerror',lambda e:errs.append(str(e)))
        await login(st,'aarav@doubtdesk.demo','student123'); await st.wait_for_timeout(500)
        await shot(st,'s01-student-home')
        rows=await st.locator('.doubt-row').count(); chk('student home lists only active doubts', rows==1 and 'Integration' not in await st.locator('main').inner_text(), rows)
        chk('resolved link present', await st.locator('.resolved-link').count()==1, await st.locator('.resolved-link').inner_text())
        chk('turn cue on active doubt', 'Waiting for your educator' in await st.locator('.doubt-row').first.inner_text())
        chk('student excerpt shows no raw fences', '```' not in await st.locator('main').inner_text())
        await st.click('.resolved-link a'); await st.wait_for_selector('text=Resolved doubts'); await shot(st,'s02-student-resolved')
        chk('resolved page shows resolved doubt', 'Integration by parts' in await st.locator('main').inner_text())
        await st.click('.back-link a'); await st.wait_for_selector('.page-title')
        # ask with code + image
        await st.click('text=+ Ask a doubt'); await st.select_option('select',label='CS301 - Computer Science')
        await st.fill('textarea','Why does my merge sort use O(n) extra space? Can it be done in place?\n```\nvoid merge(a,l,m,r){ /* copy to tmp */ }\n```')
        await st.set_input_files('input[type=file]','/tmp/note.png'); await st.click('button:has-text("Submit doubt")')
        await st.wait_for_selector('.thread-head'); await st.wait_for_timeout(400); await shot(st,'s03-after-submit')
        chk('submit lands on thread with confirmation', await st.locator('.toast-ok').count()==1 and '/doubt/' in st.url, st.url)
        title=await st.locator('.thread-head h2').inner_text(); chk('title has no code fence', '```' not in title, title)
        chk('code rendered as code block', await st.locator('.thread-head pre.code-block').count()==1)
        tid=st.url.split('/doubt/')[1].split('?')[0]
        # educator inbox
        await login(ed,'educator@doubtdesk.demo','educator123'); await ed.wait_for_timeout(600); await shot(ed,'e01-educator-needs-reply')
        tabs=await ed.locator('.tab').all_inner_texts(); print(tabs)
        r401=ed.locator('.doubt-card',has_text='HTTP 401'); t=await r401.inner_text()
        chk('401/403 (student replied last) is Ongoing, not Answered', 'in progress' in t.lower() and 'answered' not in t.lower(), t[:80].replace(chr(10),' '))
        chk('owed-reply row: primary is reply, no Mark resolved', 'Reply to follow-up' in t and 'Mark resolved' not in t, t[-60:].replace(chr(10),' '))
        chk('reply button is the primary (filled) style', 'btn-ghost' not in (await r401.locator('a.btn').get_attribute('class')))
        await ed.click('.tab:has-text("Answered")'); await ed.wait_for_timeout(500)
        ans=await ed.locator('.doubt-card').all_inner_texts(); chk('Answered tab only holds educator-last doubts', all('Student replied' not in a and 'New ·' not in a for a in ans), len(ans))
        chk('Answered rows offer Mark resolved', all('Mark resolved' in a for a in ans))
        await ed.click('.tab:has-text("Needs reply")'); await ed.wait_for_timeout(400)
        first=await ed.locator('.doubt-title').first.inner_text(); print('first needs-reply:',first)
        texts=await ed.locator('.doubt-title').all_inner_texts()
        chk('longest-waiting first (new doubt last among needs reply)', 'merge sort' in texts[-1], texts)
        # open tab + start working
        await ed.click('.tab:has-text("Open")'); await ed.wait_for_timeout(500); chk('tab in url', 'tab=open' in ed.url, ed.url)
        card=ed.locator('.doubt-card',has_text='merge sort'); await card.locator('button:has-text("Start working")').click(); await ed.wait_for_timeout(700)
        await shot(ed,'e02-moved-toast'); chk('toast with undo shown', await ed.locator('.toast').count()==1, await ed.locator('.toast').inner_text())
        await ed.locator('.toast button').click(); await ed.wait_for_timeout(600)
        chk('undo returns doubt to Open', await ed.locator('.doubt-card',has_text='merge sort').count()==1)
        await ed.locator('.doubt-card',has_text='merge sort').locator('button:has-text("Start working")').click(); await ed.wait_for_timeout(500)
        await ed.click('.tab:has-text("Ongoing")'); await ed.wait_for_timeout(600); chk('doubt now in Ongoing tab', await ed.locator('.doubt-card',has_text='merge sort').count()==1)
        await shot(ed,'e03-ongoing-tab')
        await ed.locator('.doubt-card a',has_text='merge sort').click(); await ed.wait_for_selector('.thread-head'); await shot(ed,'e04-edu-thread-before-reply')
        chk('educator thread shows your-turn banner', 'Your turn' in await ed.locator('.turn-banner').inner_text())
        await ed.go_back(); await ed.wait_for_selector('.tabs'); chk('tab kept after back', 'tab=in_progress' in ed.url and 'is-active' in await ed.locator('.tab:has-text("Ongoing")').get_attribute('class'), ed.url)
        # filter preserved
        await ed.select_option('.filter-bar select',label='CS301 - Computer Science'); await ed.locator('.doubt-card a').first.click(); await ed.wait_for_selector('.thread-head'); await ed.go_back(); await ed.wait_for_selector('.tabs')
        chk('course filter survives open+back', 'course=' in ed.url and await ed.locator('.filter-bar select').input_value()!='', ed.url)
        await ed.goto(B+'/#/doubt/'+tid); await ed.wait_for_selector('.thread-head')
        # live update
        await ed.fill('.reply-box textarea','Merge in place with rotations. Example:\n```\nrotate(a,m,r);\n```'); await ed.click('.reply-box button[type=submit]'); await ed.wait_for_timeout(900)
        chk('educator status becomes Answered', 'answered' in (await ed.locator('.thread-head .chip').inner_text()).lower())
        await ed.screenshot(path='/tmp/shots3/e05-edu-after-reply.png',full_page=True)
        await st.wait_for_timeout(12000)
        chk('student open thread updates without reload', await st.locator('.msg').count()==1, await st.locator('.turn-banner').inner_text())
        await shot(st,'s04-student-thread-live-reply')
        chk('code block in reply', await st.locator('.msg pre.code-block').count()==1)
        await st.goto(B+'/#/my'); await st.reload(); await st.wait_for_selector('.doubt-row'); await shot(st,'s05-student-home-your-turn')
        chk('student list shows your-turn cue', 'Educator replied · your turn' in await st.locator('.doubt-row').first.inner_text())
        # student resolves
        await st.locator('.doubt-row').first.click(); await st.wait_for_selector('.thread-head')
        await st.click('button:has-text("This solved it")'); await st.wait_for_timeout(700)
        chk('student can mark resolved', 'resolved' in (await st.locator('.thread-head .chip').inner_text()).lower())
        await shot(st,'s06-student-resolved-thread')
        await st.goto(B+'/#/my'); await st.reload(); await st.wait_for_selector('.page-title')
        await st.wait_for_timeout(1000); body=await st.locator('main').inner_text(); chk('resolved doubt leaves active home', 'merge sort' not in body, body[:200].replace(chr(10),' | '))
        # follow up after resolved -> educator sees follow-up cue
        await st.goto(B+'/#/doubt/'+tid); await st.reload(); await st.wait_for_selector('.thread-head')
        await st.fill('.reply-box textarea','Does this stay stable?'); await st.click('button:has-text("Send")'); await st.wait_for_timeout(800)
        await ed.goto(B+'/#/inbox'); await ed.reload(); await ed.wait_for_selector('.tabs'); await ed.wait_for_timeout(500)
        row=ed.locator('.doubt-card',has_text='merge sort'); chk('educator sees follow-up cue in Needs reply', await row.count()==1 and 'Student replied' in await row.inner_text(), await row.inner_text() if await row.count() else '')
        await shot(ed,'e06-followup-cue')
        # errors
        sc2=await mk(); s2=await sc2.new_page(); s2.on('pageerror',lambda e:errs.append(str(e))); await login(s2,'sara@doubtdesk.demo','student123')
        await s2.goto(B+'/#/doubt/'+tid); await s2.reload(); await s2.wait_for_timeout(1000); await shot(s2,'x01-foreign-doubt')
        chk('foreign doubt shows message not blank', 'Could not open' in await s2.locator('body').inner_text(), (await s2.locator('body').inner_text())[:90])
        await s2.goto(B+'/#/doubt/99999'); await s2.reload(); await s2.wait_for_timeout(800); chk('missing doubt shows message', 'Could not open' in await s2.locator('body').inner_text())
        await st.route('**/api/doubts/*/messages', lambda r: r.abort()); await st.fill('.reply-box textarea','will fail'); await st.click('button:has-text("Send")'); await st.wait_for_timeout(800)
        await shot(st,'x02-send-failure'); chk('failed send keeps thread and draft with message', await st.locator('.thread-head').count()==1 and await st.locator('.reply-box textarea').input_value()=='will fail' and await st.locator('.form-error').count()==1)
        await st.unroute('**/api/doubts/*/messages')
        # mobile
        for who,em,pw,home in [('student','aarav@doubtdesk.demo','student123','/#/my'),('educator','educator@doubtdesk.demo','educator123','/#/inbox')]:
            mc=await mk(390,844,True); mp=await mc.new_page(); mp.on('pageerror',lambda e:errs.append(str(e))); await login(mp,em,pw); await mp.goto(B+home); await mp.reload(); await mp.wait_for_timeout(900)
            await shot(mp,f'm-{who}-home')
            if who=='educator':
                bx=await mp.evaluate("[...document.querySelectorAll('.tab')].map(e=>{const r=e.getBoundingClientRect();return [Math.round(r.left),Math.round(r.right)]})"); chk('mobile educator: all 5 tabs visible within viewport, no swipe needed', len(bx)==5 and all(l>=0 and r<=390 for l,r in bx), bx)
                await mp.screenshot(path='/tmp/shots3/m-educator-viewport.png'); sw=await mp.evaluate('[document.documentElement.scrollWidth, innerWidth]'); chk(f'mobile {who} home no overflow', sw[0]==sw[1], sw)
            await mp.goto(B+'/#/doubt/'+tid); await mp.reload(); await mp.wait_for_selector('.thread-head'); await mp.wait_for_timeout(500); await shot(mp,f'm-{who}-thread')
            sw=await mp.evaluate('[document.documentElement.scrollWidth, innerWidth]'); chk(f'mobile {who} thread (with image) no overflow', sw[0]==sw[1], sw)
            await mp.evaluate('window.scrollTo(0, 500)'); await mp.wait_for_timeout(300)
            top=await mp.evaluate("document.querySelector('.topbar').getBoundingClientRect().top"); chk(f'mobile {who} sticky header stays at viewport top while scrolling', top==0, top)
            await mp.screenshot(path=f'/tmp/shots3/m-{who}-thread-scrolled.png'); await mp.evaluate('window.scrollTo(0, 0)')
            h=await mp.evaluate("[...document.querySelectorAll('button,select,input[type=text],input:not([type=file]),.tab')].filter(e=>e.offsetParent).map(e=>Math.round(e.getBoundingClientRect().height))"); chk(f'mobile {who} tap targets >=44', min(h)>=44, h)
        chk('no uncaught page errors during run', not errs, errs)
        await br.close()
    json.dump(res,open('/tmp/e2e3.json','w'),indent=1)
asyncio.run(main())
